+
+func runInitAgentsForTest(t *testing.T, repo string) {
+	t.Helper()
+	var out bytes.Buffer
+	if err := Run(context.Background(), Options{Stdout: &out, Stderr: &out}, []string{"init-agents", "--repo", repo}); err != nil {
+		t.Fatal(err)
+	}
